Script:
$ErrorActionPreference='Stop'
Set-Location 'F:\.codex\worktrees\ecs-relations-worker-3\SomeEngine.Next'
$series='focused-native-r42'
$control="artifacts/relations-measurements/$series"
$reports="artifacts/ecs-relations/measurements/$series"
$evidence="docs/evidence/ECS-Relations-2026-10-19/$series"
$source=Get-Content -LiteralPath "$control/source.json" -Raw|ConvertFrom-Json
$master=Get-Content -LiteralPath 'artifacts/benchmark-queue/ce5e67425e8c4210b26be676818ac1cd/result.json' -Raw|ConvertFrom-Json
$preparation=Get-Content -LiteralPath "$control/preparation.json" -Raw|ConvertFrom-Json
$ready=Get-Content -LiteralPath "$control/watcher-ready.json" -Raw|ConvertFrom-Json
$submissions=@(Get-Content -LiteralPath "$reports/submissions.json" -Raw|ConvertFrom-Json)
$submission=Get-Content -LiteralPath "$reports/queue-submission.json" -Raw|ConvertFrom-Json
$analysis=Get-Content -LiteralPath "artifacts/benchmark-queue/$($submission.Reports[0].QueueId)/result.json" -Raw|ConvertFrom-Json
$stages=@(Get-Content -LiteralPath "$reports/postprocess-stages.json" -Raw|ConvertFrom-Json)
$cases=@(foreach($item in $submissions){
    $queue=Get-Content -LiteralPath "artifacts/benchmark-queue/$($item.QueueId)/result.json" -Raw|ConvertFrom-Json
    [pscustomobject]@{CaseId=$item.CaseId;SourceCommit=$item.SourceCommit;Queue=$queue}
})
$ordered=@($cases|Sort-Object{[DateTimeOffset]$_.Queue.StartedAtUtc})
$first=$ordered[0].Queue
$last=$ordered[-1].Queue
function Seconds($start,$finish){([DateTimeOffset]$finish-[DateTimeOffset]$start).TotalSeconds}
$execution=($ordered|ForEach-Object{Seconds $_.Queue.StartedAtUtc $_.Queue.FinishedAtUtc}|Measure-Object -Sum).Sum
$between=@(for($i=1;$i -lt $ordered.Count;$i++){
    [pscustomobject]@{BeforeCaseId=$ordered[$i-1].CaseId;AfterCaseId=$ordered[$i].CaseId;Seconds=(Seconds $ordered[$i-1].Queue.FinishedAtUtc $ordered[$i].Queue.StartedAtUtc)}
})
$observation=[pscustomobject]@{ProcessStartedAtUtc='2026-10-20T00:13:02Z';ObservationStartedAtUtc='2026-10-20T00:13:02Z';ObservationEndedAtUtc='2026-10-20T00:13:21Z';Kind='Root queue control metadata';Detail='External Bistro python64744 started00:10:29.519790Z and remained running00:13:20.2195364Z; both selected cases were queued.'}
$observation|ConvertTo-Json -Depth 5|Set-Content -LiteralPath "$control/control-observation.json" -Encoding utf8
$observationOverlaps=@($cases|Where-Object{[DateTimeOffset]$_.Queue.StartedAtUtc -lt [DateTimeOffset]$observation.ObservationEndedAtUtc -and [DateTimeOffset]$_.Queue.FinishedAtUtc -gt [DateTimeOffset]$observation.ProcessStartedAtUtc})
$summary=[pscustomobject]@{
    Series=$series;SourceCommit=$source.SourceCommit;CaseCount=$cases.Count
    PreparationExitCode=$master.ExitCode;CaseExitCodes=@($cases.Queue.ExitCode|Select-Object -Unique);AnalysisExitCodes=@($analysis.ExitCode)
    LastCaseSubmittedAtUtc=$preparation.LastCaseSubmittedAtUtc;PreparationFinishedAtUtc=$master.FinishedAtUtc
    FirstCaseStartedAtUtc=$first.StartedAtUtc;LastCaseFinishedAtUtc=$last.FinishedAtUtc;FirstAnalysisStartedAtUtc=$analysis.StartedAtUtc
    AllCasesSubmittedBeforeExecution=([DateTimeOffset]$preparation.LastCaseSubmittedAtUtc -le [DateTimeOffset]$first.StartedAtUtc)
    PreparationFinishedBeforeExecution=([DateTimeOffset]$master.FinishedAtUtc -le [DateTimeOffset]$first.StartedAtUtc)
    AnalysisStartedAfterExecution=([DateTimeOffset]$analysis.StartedAtUtc -ge [DateTimeOffset]$last.FinishedAtUtc)
    QuietPassed=([DateTimeOffset]$preparation.InitialObservationEndedAtUtc -le [DateTimeOffset]$first.StartedAtUtc -and $observationOverlaps.Count -eq 0)
    CaseExecutionSeconds=$execution;BetweenCasesSeconds=($between.Seconds|Measure-Object -Sum).Sum
    AnalysisExecutionSeconds=(Seconds $analysis.StartedAtUtc $analysis.FinishedAtUtc)
    SubmissionToAnalysisFinishedSeconds=(Seconds $master.SubmittedAtUtc $analysis.FinishedAtUtc)
}
$boundary=[pscustomobject]@{
    Summary=$summary;Preparation=$master;BatchPreparation=$preparation;Cases=$cases;Analyses=@($analysis)
    PostprocessStages=$stages;BetweenCases=$between;WatcherReady=$ready;ControlObservation=$observation;ControlObservationOverlaps=@($observationOverlaps.CaseId)
    RootHostRelease=(Get-Content -LiteralPath "$control/root-host-released.json" -Raw|ConvertFrom-Json)
    NativeReaderRelease=(Get-Content -LiteralPath "$control/native-reader-released.json" -Raw|ConvertFrom-Json)
}
$boundary|ConvertTo-Json -Depth 12|Set-Content -LiteralPath "$evidence/queue-boundaries.json" -Encoding utf8
$summary|ConvertTo-Json -Depth 6|Set-Content -LiteralPath "$evidence/queue-timing-summary.json" -Encoding utf8
foreach($file in Get-ChildItem -LiteralPath $control -File -Filter '*.json'){Copy-Item -LiteralPath $file.FullName -Destination $evidence -Force}
foreach($id in @('a336a5220d8d4cd4804d0d485cbc3ef1','428d7336fde641c09cc3a5010783ece2','fad87b7ff27e41339f6665b71e9eef36','734696c3200a437bb1f61a2b09f541b9','16edbce2c6204e5280e7021ed442d137',$master.Id,$analysis.Id)+@($cases.Queue.Id)){
    $directory=Join-Path $evidence "queues/$id"
    New-Item -ItemType Directory -Path $directory -Force|Out-Null
    foreach($name in @('result.json','stdout.log','stderr.log')){Copy-Item -LiteralPath "artifacts/benchmark-queue/$id/$name" -Destination $directory -Force}
}
$approved=Get-Content -LiteralPath "$evidence/approved-summary.json" -Raw|ConvertFrom-Json
$previous=Get-Content -LiteralPath 'docs/evidence/ECS-Relations-2026-10-19/focused-native-r41/approved-summary.json' -Raw|ConvertFrom-Json
$gc=[Collections.Generic.List[object]]::new()
$comparison=[Collections.Generic.List[object]]::new()
foreach($item in $submissions){
    $report=Get-Content -LiteralPath $item.Report -Raw|ConvertFrom-Json
    foreach($metric in @($approved.Metrics|Where-Object{$_.Required -and $_.CaseId -eq $item.CaseId})){
        foreach($side in @('relation','handwritten')){
            $samples=@($report.RawSamples|Where-Object{$_.Side -eq $side -and $_.Boundary -eq $metric.Boundary})
            $gc.Add([pscustomobject]@{CaseId=$item.CaseId;Boundary=$metric.Boundary;Side=$side;Samples=$samples.Count;Gen0=($samples.Gen0|Measure-Object -Sum).Sum;Gen1=($samples.Gen1|Measure-Object -Sum).Sum;Gen2=($samples.Gen2|Measure-Object -Sum).Sum;NonzeroGcFrames=@($samples|Where-Object{$_.Gen0 -ne 0 -or $_.Gen1 -ne 0 -or $_.Gen2 -ne 0}).Count})
        }
        $old=$previous.Metrics|Where-Object{$_.Required -and $_.CaseId -eq $item.CaseId -and $_.Boundary -eq $metric.Boundary}
        $comparison.Add([pscustomobject]@{CaseId=$item.CaseId;Boundary=$metric.Boundary;PreviousSourceCommit=$previous.Summary.SourceCommit;CurrentSourceCommit=$source.SourceCommit;PreviousMedianRatio=$old.MedianRatio;CurrentMedianRatio=$metric.MedianRatio;PreviousP95Ratio=$old.P95Ratio;CurrentP95Ratio=$metric.P95Ratio;CurrentRelationMedianTicks=$metric.RelationMedianTicks;CurrentHandwrittenMedianTicks=$metric.HandwrittenMedianTicks;CurrentRelationP95Ticks=$metric.RelationP95Ticks;CurrentHandwrittenP95Ticks=$metric.HandwrittenP95Ticks;Frequency=$metric.Frequency;ApprovedPassed=$metric.ApprovedPassed})
    }
}
$gc|ConvertTo-Json -Depth 5|Set-Content -LiteralPath "$evidence/gc-by-boundary.json" -Encoding utf8
$comparison|ConvertTo-Json -Depth 5|Set-Content -LiteralPath "$evidence/previous-source-comparison.json" -Encoding utf8
Write-Output ('R42_BOUNDARIES '+($summary|ConvertTo-Json -Depth 5 -Compress))
Write-Output ('R42_APPROVED '+($approved.Summary|ConvertTo-Json -Compress))
Write-Output ('R42_GC '+($gc|Where-Object{$_.NonzeroGcFrames -ne 0 -or $_.Samples -ne 256}|ConvertTo-Json -Depth 5 -Compress))

$latest=[Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal)
$seriesNames=@('final-native-r38','focused-native-r39','focused-native-r41','focused-native-r42')
foreach($selectedSeries in $seriesNames){
 $selectedRoot="docs/evidence/ECS-Relations-2026-10-19/$selectedSeries"
 $selectedBoundary=Get-Content -LiteralPath "$selectedRoot/queue-boundaries.json" -Raw|ConvertFrom-Json
 $selectedIndex=@(Get-Content -LiteralPath "$selectedRoot/index.json" -Raw|ConvertFrom-Json)
 $selectedApproved=Get-Content -LiteralPath "$selectedRoot/approved-summary.json" -Raw|ConvertFrom-Json
 foreach($case in $selectedBoundary.Cases){
  $entry=@($selectedIndex|Where-Object CaseId -eq $case.CaseId)[0]
  $required=@($selectedApproved.Metrics|Where-Object{$_.Required -and $_.CaseId -eq $case.CaseId})
  $completed=[DateTimeOffset]$case.Queue.FinishedAtUtc
  $row=[pscustomobject]@{
   CaseId=$case.CaseId;Class=$required[0].Class;Series=$selectedSeries;SourceCommit=$entry.SourceCommit
   QueueId=$case.Queue.Id;FinishedAtUtc=$completed.ToUniversalTime().ToString('O');ExitCode=$case.Queue.ExitCode
   Backend=$entry.Backend;Equal=$entry.Equal;RequiredCount=$required.Count
   StrictPassed=(@($required|Where-Object Passed).Count -eq $required.Count)
   ApprovedPassed=(@($required|Where-Object ApprovedPassed).Count -eq $required.Count)
   ApprovedRatioLimit=1.01;Raw="$selectedRoot/$($entry.Report)"
   Metrics="$selectedRoot/metrics.csv";Index="$selectedRoot/index.json";Report="$selectedRoot/summary.md"
   RequiredResults=$required
  }
  if(!$latest.ContainsKey($case.CaseId) -or $completed -gt [DateTimeOffset]$latest[$case.CaseId].FinishedAtUtc){
   $latest[$case.CaseId]=$row
  }
 }
}
$coverage=@($latest.Values|Sort-Object CaseId)
$requiredCount=($coverage.RequiredCount|Measure-Object -Sum).Sum
$strictCount=(@($coverage.RequiredResults|Where-Object Passed)).Count
$approvedCount=(@($coverage.RequiredResults|Where-Object ApprovedPassed)).Count
$sourceCounts=@(foreach($selectedSeries in $seriesNames){
 $items=@($coverage|Where-Object Series -eq $selectedSeries)
 [pscustomobject]@{Series=$selectedSeries;SourceCommit=$items[0].SourceCommit;Cases=$items.Count;Required=($items.RequiredCount|Measure-Object -Sum).Sum}
})
$coverageSummary=[pscustomobject]@{Cases=$coverage.Count;Equal=@($coverage|Where-Object Equal).Count;Required=$requiredCount;StrictPassed=$strictCount;ApprovedPassed=$approvedCount;ApprovedUnmet=($requiredCount-$approvedCount);ApprovedRatioLimit=1.01;Sources=$sourceCounts}
$coverageRecord=[pscustomobject]@{SelectionRule='Latest completed full case by FinishedAtUtc; each source result is retained.';GeneratedAtUtc=[DateTime]::UtcNow.ToString('O');Summary=$coverageSummary;Cases=$coverage}
$coverageRecord|ConvertTo-Json -Depth 14|Set-Content -LiteralPath "$evidence/latest-case-coverage.json" -Encoding utf8
$coverage|Select-Object CaseId,Class,Series,SourceCommit,QueueId,FinishedAtUtc,ExitCode,Backend,Equal,RequiredCount,StrictPassed,ApprovedPassed,ApprovedRatioLimit,Raw,Metrics,Index,Report,@{Name='RequiredResults';Expression={ConvertTo-Json -InputObject @($_.RequiredResults) -Depth 5 -Compress}}|Export-Csv -LiteralPath "$evidence/latest-case-coverage.csv" -NoTypeInformation -Encoding utf8
$coverageSummary|ConvertTo-Json -Depth 5|Set-Content -LiteralPath "$evidence/latest-case-coverage-summary.json" -Encoding utf8
Write-Output ('LATEST_COVERAGE '+($coverageSummary|ConvertTo-Json -Depth 5 -Compress))
Write-Output ('R42_METRICS '+($approved.Metrics|Select-Object CaseId,Boundary,RelationMedianTicks,HandwrittenMedianTicks,MedianRatio,RelationP95Ticks,HandwrittenP95Ticks,P95Ratio,RelationTotalFrameAllocatedBytes,HandwrittenTotalFrameAllocatedBytes,ApprovedPassed|ConvertTo-Json -Compress))
Remove-Item -LiteralPath $PSCommandPath
exit 0
